mapper.select:
SELECT u.*, b.booking_no, c.court_name
FROM court_usage_record u
JOIN booking b ON b.booking_id = u.booking_id
JOIN court c ON c.court_id = u.court_id


        AND u.court_id = #{courtId}


        AND b.member_id = #{memberId}


        AND u.actual_end_at >= #{from}


        AND u.actual_start_at < DATE_ADD(#{to}, INTERVAL 1 DAY)


ORDER BY u.actual_start_at DESC
